SELECT md.chembl_id, md.pref_name, cs.canonical_smiles, di.efo_id AS indication_curie, di.efo_term AS indication_label, di.max_phase_for_ind FROM molecule_dictionary md JOIN drug_indication di ON md.molregno = di.molregno JOIN compound_structures cs ON md.molregno = cs.molregno WHERE di.max_phase_for_ind = 4 AND di.efo_term = 'chronic kidney disease' ORDER BY md.chembl_id ASC, md.pref_name ASC, cs.canonical_smiles ASC, di.efo_id ASC, di.efo_term ASC, di.max_phase_for_ind ASC
